mapper.update:
update shopping_cart set number=number-1

    user_id = #{userId} and number > 0
    and dish_id = #{dishId}
    and dish_flavor = #{dishFlavor}
    and setmeal_id = #{setmealId}

mapper.select:
select * from shopping_cart

    user_id = #{userId}
    and dish_id = #{dishId}
    and dish_flavor = #{dishFlavor}
    and setmeal_id = #{setmealId}

limit 1

mapper.delete:
delete from shopping_cart

    user_id = #{userId}
    and dish_id = #{dishId}
    and dish_flavor = #{dishFlavor}
    and setmeal_id = #{setmealId}
